function App() {
  const [loaded, setLoaded] = useState(false);
  useEffect(() => { const t = setTimeout(() => setLoaded(true), 1000); return () => clearTimeout(t); }, []);
  const box = { width: 200, background: '#cde', display: 'flex', alignItems: 'center', justifyContent: 'center' };
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16, display: 'flex', gap: 24 }}>
      <div>
        <p>Reserved (like next/image)</p>
        <div style={{ ...box, height: 120 }}>{loaded ? 'image' : 'loading…'}</div>
        <p>Caption stays put ✅</p>
      </div>
      <div>
        <p>No reserved height</p>
        <div style={{ ...box, height: loaded ? 120 : 0 }}>{loaded ? 'image' : ''}</div>
        <p>Caption jumps down ❌</p>
      </div>
    </div>
  );
}

function App() {
  // Illustrative comparison of usage in a Next.js component:
  const plain = [
    '// Plain <img> — no optimization, risks CLS + oversized download',
    '<img src="/hero.jpg" alt="Hero" />',
  ];
  const next = [
    '// next/image — resized, WebP/AVIF, lazy, space reserved',
    "import Image from 'next/image';",
    '<Image src="/hero.jpg" width={1600} height={900} priority alt="Hero" />',
  ];
  return (
    <pre style={{ fontFamily: 'ui-monospace, monospace', padding: 16, fontSize: 12 }}>
      {plain.join('\n')}
      {'\n\n'}
      {next.join('\n')}
    </pre>
  );
}

